    "demo": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Combobox demo</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n        --bg: #ffffff;\n        --fg: #1a1a1a;\n        --hl: #dbe6fd;\n        --accent: #0b57d0;\n      }\n      @media (prefers-color-scheme: dark) {\n        :root {\n          --bg: #121212;\n          --fg: #f0f0f0;\n          --hl: #263248;\n          --accent: #8ab4f8;\n        }\n      }\n      body {\n        margin: 0;\n        padding: 2rem 1rem;\n        font:\n          1rem/1.5 system-ui,\n          sans-serif;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      main {\n        max-width: 40rem;\n        margin: 0 auto;\n      }\n      .field {\n        position: relative;\n        max-width: 20rem;\n      }\n      label {\n        display: block;\n        font-weight: 600;\n        margin-bottom: 0.25rem;\n      }\n      input {\n        box-sizing: border-box;\n        width: 100%;\n        font: inherit;\n        padding: 0.5rem;\n        border: 2px solid var(--fg);\n        border-radius: 0.375rem;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      :focus-visible {\n        outline: 3px solid var(--accent);\n        outline-offset: 2px;\n      }\n      [role=\"listbox\"] {\n        position: absolute;\n        left: 0;\n        right: 0;\n        margin: 0.25rem 0 0;\n        padding: 0.25rem;\n        list-style: none;\n        border: 2px solid var(--fg);\n        border-radius: 0.375rem;\n        background: var(--bg);\n        max-height: 12rem;\n        overflow-y: auto;\n        z-index: 1;\n      }\n      [role=\"option\"] {\n        padding: 0.375rem 0.5rem;\n        border-radius: 0.25rem;\n        cursor: pointer;\n      }\n      [role=\"option\"][aria-selected=\"true\"] {\n        background: var(--hl);\n        outline: 2px solid var(--accent);\n        outline-offset: -2px;\n      }\n      .visually-hidden {\n        position: absolute;\n        width: 1px;\n        height: 1px;\n        margin: -1px;\n        padding: 0;\n        overflow: hidden;\n        clip-path: inset(50%);\n        white-space: nowrap;\n        border: 0;\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <h1>Find a store</h1>\n      <div class=\"field\">\n        <label for=\"city\">City</label>\n        <input\n          id=\"city\"\n          type=\"text\"\n          role=\"combobox\"\n          autocomplete=\"off\"\n          aria-autocomplete=\"list\"\n          aria-expanded=\"false\"\n          aria-controls=\"city-list\"\n        />\n        <ul id=\"city-list\" role=\"listbox\" aria-label=\"Cities\" hidden></ul>\n      </div>\n      <div id=\"city-status\" role=\"status\" class=\"visually-hidden\"></div>\n      <p id=\"chosen\"></p>\n    </main>\n    <script>\n      const cities = [\n        \"Amsterdam\",\n        \"Athens\",\n        \"Barcelona\",\n        \"Berlin\",\n        \"Bratislava\",\n        \"Brno\",\n        \"Brussels\",\n        \"Budapest\",\n        \"Copenhagen\",\n        \"Dublin\",\n        \"Helsinki\",\n        \"Lisbon\",\n        \"Ljubljana\",\n        \"Madrid\",\n        \"Paris\",\n        \"Prague\",\n        \"Riga\",\n        \"Rome\",\n        \"Sofia\",\n        \"Stockholm\",\n        \"Tallinn\",\n        \"Vienna\",\n        \"Vilnius\",\n        \"Warsaw\",\n        \"Zagreb\",\n      ];\n      const input = document.getElementById(\"city\");\n      const list = document.getElementById(\"city-list\");\n      const status = document.getElementById(\"city-status\");\n      const chosen = document.getElementById(\"chosen\");\n      let timer;\n\n      function render(matches) {\n        list.replaceChildren(\n          ...matches.map((city, i) => {\n            const li = document.createElement(\"li\");\n            li.id = \"city-opt-\" + i;\n            li.setAttribute(\"role\", \"option\");\n            li.setAttribute(\"aria-selected\", \"false\");\n            li.textContent = city;\n            return li;\n          })\n        );\n        setOpen(matches.length > 0);\n        clearTimeout(timer);\n        timer = setTimeout(() => {\n          status.textContent =\n            matches.length === 0\n              ? \"No cities found\"\n              : matches.length +\n                (matches.length === 1 ? \" city\" : \" cities\") +\n                \" available\";\n        }, 300);\n      }\n      function setOpen(open) {\n        list.hidden = !open;\n        input.setAttribute(\"aria-expanded\", String(open));\n        if (!open) input.removeAttribute(\"aria-activedescendant\");\n      }\n      const options = () => [...list.querySelectorAll('[role=\"option\"]')];\n      const current = () =>\n        options().findIndex(\n          (o) => o.id === input.getAttribute(\"aria-activedescendant\")\n        );\n      function highlight(option) {\n        for (const o of options())\n          o.setAttribute(\"aria-selected\", String(o === option));\n        input.setAttribute(\"aria-activedescendant\", option.id);\n        option.scrollIntoView({ block: \"nearest\" });\n      }\n      function accept(option) {\n        input.value = option.textContent;\n        chosen.textContent = \"Showing stores in \" + option.textContent + \".\";\n        setOpen(false);\n      }\n      const filter = () => {\n        const q = input.value.trim().toLowerCase();\n        return q === \"\"\n          ? []\n          : cities.filter((c) => c.toLowerCase().startsWith(q));\n      };\n\n      input.addEventListener(\"input\", () => render(filter()));\n      input.addEventListener(\"keydown\", (e) => {\n        const opts = options();\n        if (e.key === \"ArrowDown\" || e.key === \"ArrowUp\") {\n          e.preventDefault();\n          if (list.hidden) {\n            render(input.value ? filter() : cities);\n          }\n          const all = options();\n          if (all.length === 0) return;\n          const i = current();\n          const next =\n            e.key === \"ArrowDown\"\n              ? (i + 1) % all.length\n              : i <= 0\n                ? all.length - 1\n                : i - 1;\n          highlight(all[next]);\n        } else if (e.key === \"Enter\") {\n          const i = current();\n          if (!list.hidden && i >= 0) {\n            e.preventDefault();\n            accept(opts[i]);\n          }\n        } else if (e.key === \"Escape\") {\n          if (!list.hidden) setOpen(false);\n          else input.value = \"\";\n        } else if (e.key === \"Tab\") {\n          setOpen(false);\n        }\n      });\n      input.addEventListener(\"blur\", () => setOpen(false));\n      list.addEventListener(\"pointerdown\", (e) => e.preventDefault());\n      list.addEventListener(\"click\", (e) => {\n        const option = e.target.closest('[role=\"option\"]');\n        if (option) accept(option);\n      });\n    </script>\n  </body>\n</html>\n",
    "description": "Build an accessible autocomplete, typeahead, searchable picker (country, city) or search suggestions input with role combobox, listbox and aria-activedescendant",
    "expectations": "# Expectations: combobox-autocomplete\n\n1. The text input has role `combobox`, an accessible name from a visible label, and `aria-expanded=\"false\"` before typing.\n2. Typing a letter that matches options shows an element with role `listbox` and sets `aria-expanded=\"true\"` on the input.\n3. Pressing Arrow Down keeps `document.activeElement` on the input and sets its `aria-activedescendant` to the id of an element with role `option` and `aria-selected=\"true\"`.\n4. Pressing Enter after highlighting an option puts that option's text in the input and sets `aria-expanded=\"false\"`.\n5. Pressing Escape with the list open hides the listbox and sets `aria-expanded=\"false\"`, with focus still on the input.\n6. After typing, an element with role `status` (or `aria-live`) that existed before typing contains the number of available results.\n",
