    "demo": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Confirm before a purchase demo</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n        --bg: #ffffff;\n        --fg: #1a1a1a;\n        --accent: #0b57d0;\n      }\n      @media (prefers-color-scheme: dark) {\n        :root {\n          --bg: #121212;\n          --fg: #f0f0f0;\n          --accent: #8ab4f8;\n        }\n      }\n      body {\n        margin: 0;\n        padding: 2rem 1rem;\n        font:\n          1rem/1.5 system-ui,\n          sans-serif;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      main {\n        max-width: 32rem;\n        margin: 0 auto;\n      }\n      .field {\n        margin-bottom: 1rem;\n      }\n      label {\n        display: block;\n        font-weight: 600;\n      }\n      .check {\n        font-weight: 400;\n      }\n      input:not([type=\"checkbox\"]) {\n        box-sizing: border-box;\n        width: 100%;\n        padding: 0.5rem;\n        font: inherit;\n      }\n      fieldset {\n        margin: 0 0 1rem;\n        border: 1px solid currentColor;\n      }\n      button {\n        padding: 0.5rem 1rem;\n        font: inherit;\n      }\n      :focus-visible {\n        outline: 3px solid var(--accent);\n        outline-offset: 2px;\n      }\n      dialog {\n        max-width: 24rem;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      dialog::backdrop {\n        background: rgb(0 0 0 / 0.5);\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <h1>Outdoor gear</h1>\n      <section id=\"product\">\n        <h2>Rain jacket</h2>\n        <p>€189.00</p>\n        <button type=\"button\" id=\"buy\">Buy now</button>\n      </section>\n      <section id=\"placed\" hidden>\n        <h2>Thank you</h2>\n        <p>Your order is on its way.</p>\n      </section>\n    </main>\n    <dialog id=\"confirm-order\" aria-labelledby=\"confirm-title\">\n      <h2 id=\"confirm-title\">Confirm your order</h2>\n      <p>Rain jacket, €189.00, to Jana Nováková, Hlavní 1, 602 00 Brno.</p>\n      <form method=\"dialog\">\n        <button value=\"cancel\">Cancel</button>\n        <button value=\"place\" autofocus>Place order for €189.00</button>\n      </form>\n    </dialog>\n    <script>\n      const dialog = document.getElementById(\"confirm-order\");\n\n      document.getElementById(\"buy\").addEventListener(\"click\", () => {\n        dialog.returnValue = \"\";\n        dialog.showModal();\n      });\n\n      dialog.addEventListener(\"close\", () => {\n        if (dialog.returnValue === \"place\") {\n          document.getElementById(\"product\").hidden = true;\n          document.getElementById(\"placed\").hidden = false;\n        }\n      });\n    </script>\n  </body>\n</html>\n",
