    "demo": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Accordion demo</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n        --bg: #ffffff;\n        --fg: #1a1a1a;\n        --line: #6b6b6b;\n        --accent: #0b57d0;\n      }\n      @media (prefers-color-scheme: dark) {\n        :root {\n          --bg: #121212;\n          --fg: #f0f0f0;\n          --line: #9a9a9a;\n          --accent: #8ab4f8;\n        }\n      }\n      body {\n        margin: 0;\n        padding: 2rem 1rem;\n        font:\n          1rem/1.5 system-ui,\n          sans-serif;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      main {\n        max-width: 40rem;\n        margin: 0 auto;\n      }\n      h2 {\n        margin: 0;\n        border-top: 1px solid var(--line);\n      }\n      h2 button {\n        all: unset;\n        box-sizing: border-box;\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        width: 100%;\n        padding: 1rem 0.25rem;\n        font:\n          600 1.125rem/1.4 system-ui,\n          sans-serif;\n        cursor: pointer;\n      }\n      h2 button:focus-visible {\n        outline: 3px solid var(--accent);\n        outline-offset: 2px;\n      }\n      .chevron {\n        width: 1rem;\n        height: 1rem;\n        transition: transform 0.2s;\n      }\n      [aria-expanded=\"true\"] .chevron {\n        transform: rotate(180deg);\n      }\n      @media (prefers-reduced-motion: reduce) {\n        .chevron {\n          transition: none;\n        }\n      }\n      .panel {\n        padding: 0 0.25rem 1rem;\n      }\n      a {\n        color: var(--accent);\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <h1>Frequently asked questions</h1>\n      <div class=\"accordion\">\n        <h2>\n          <button\n            type=\"button\"\n            aria-expanded=\"false\"\n            aria-controls=\"ship-panel\"\n            id=\"ship-button\"\n          >\n            Shipping\n            <svg\n              class=\"chevron\"\n              viewBox=\"0 0 16 16\"\n              aria-hidden=\"true\"\n              focusable=\"false\"\n            >\n              <path\n                d=\"M3 6l5 5 5-5\"\n                fill=\"none\"\n                stroke=\"currentColor\"\n                stroke-width=\"2\"\n              />\n            </svg>\n          </button>\n        </h2>\n        <div class=\"panel\" id=\"ship-panel\" hidden=\"until-found\">\n          <p>\n            Orders ship within two working days.\n            <a href=\"#tracking\">Track an order</a>.\n          </p>\n        </div>\n        <h2>\n          <button\n            type=\"button\"\n            aria-expanded=\"false\"\n            aria-controls=\"returns-panel\"\n            id=\"returns-button\"\n          >\n            Returns\n            <svg\n              class=\"chevron\"\n              viewBox=\"0 0 16 16\"\n              aria-hidden=\"true\"\n              focusable=\"false\"\n            >\n              <path\n                d=\"M3 6l5 5 5-5\"\n                fill=\"none\"\n                stroke=\"currentColor\"\n                stroke-width=\"2\"\n              />\n            </svg>\n          </button>\n        </h2>\n        <div class=\"panel\" id=\"returns-panel\" hidden=\"until-found\">\n          <p>\n            Unused items can be returned within 30 days.\n            <a href=\"#returns-form\">Start a return</a>.\n          </p>\n        </div>\n      </div>\n      <p id=\"tracking\">Need more help? Write to support.</p>\n      <p id=\"returns-form\">Returns are free within the EU.</p>\n    </main>\n    <script>\n      for (const button of document.querySelectorAll(\n        \"[aria-controls][aria-expanded]\"\n      )) {\n        const panel = document.getElementById(\n          button.getAttribute(\"aria-controls\")\n        );\n        const set = (open) => {\n          button.setAttribute(\"aria-expanded\", String(open));\n          if (open) panel.removeAttribute(\"hidden\");\n          else panel.setAttribute(\"hidden\", \"until-found\");\n        };\n        button.addEventListener(\"click\", () =>\n          set(button.getAttribute(\"aria-expanded\") !== \"true\")\n        );\n        panel.addEventListener(\"beforematch\", () => set(true));\n      }\n    </script>\n  </body>\n</html>\n",
    "description": "Build an accessible show/hide toggle, FAQ accordion or expandable section with aria-expanded",
