    "demo": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Hover popup demo</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n        --bg: #ffffff;\n        --fg: #1a1a1a;\n        --accent: #0b57d0;\n      }\n      @media (prefers-color-scheme: dark) {\n        :root {\n          --bg: #121212;\n          --fg: #f0f0f0;\n          --accent: #8ab4f8;\n        }\n      }\n      body {\n        margin: 0;\n        padding: 2rem 1rem;\n        font:\n          1rem/1.5 system-ui,\n          sans-serif;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      main {\n        max-width: 32rem;\n        margin: 0 auto;\n      }\n      .field {\n        margin-bottom: 1rem;\n      }\n      label {\n        display: block;\n        font-weight: 600;\n      }\n      .check {\n        font-weight: 400;\n      }\n      input:not([type=\"checkbox\"]) {\n        box-sizing: border-box;\n        width: 100%;\n        padding: 0.5rem;\n        font: inherit;\n      }\n      fieldset {\n        margin: 0 0 1rem;\n        border: 1px solid currentColor;\n      }\n      button {\n        padding: 0.5rem 1rem;\n        font: inherit;\n      }\n      :focus-visible {\n        outline: 3px solid var(--accent);\n        outline-offset: 2px;\n      }\n      .zoom {\n        position: relative;\n        display: inline-block;\n      }\n      .zoom img {\n        display: block;\n        width: 200px;\n        height: 200px;\n      }\n      .zoom-pane {\n        position: absolute;\n        top: 0;\n        left: 100%;\n        width: 320px;\n        height: 320px;\n        border: 1px solid #767676;\n        background: var(--bg) no-repeat center / 200%;\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <h1>Rain jacket</h1>\n      <div class=\"zoom\" id=\"zoom\">\n        <img\n          id=\"trigger\"\n          src=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='%23d8e8dd'/%3E%3Cpath d='M30 25h40l8 20-10 4v31H32V49l-10-4z' fill='%232f6f4f'/%3E%3C/svg%3E\"\n          width=\"200\"\n          height=\"200\"\n          alt=\"Green rain jacket with a hood\"\n        />\n        <div class=\"zoom-pane\" id=\"pane\" hidden></div>\n      </div>\n      <p>€189.00</p>\n    </main>\n    <script>\n      const zoom = document.getElementById(\"zoom\");\n      const pane = document.getElementById(\"pane\");\n      const image = document.getElementById(\"trigger\");\n      let dismissed = false;\n\n      pane.style.backgroundImage = `url(\"${image.src}\")`;\n\n      zoom.addEventListener(\"pointerenter\", () => {\n        if (!dismissed) pane.hidden = false;\n      });\n\n      zoom.addEventListener(\"pointerleave\", () => {\n        dismissed = false;\n        pane.hidden = true;\n      });\n\n      document.addEventListener(\"keydown\", (event) => {\n        if (event.key === \"Escape\" && !pane.hidden) {\n          dismissed = true;\n          pane.hidden = true;\n        }\n      });\n    </script>\n  </body>\n</html>\n",
