    "demo": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Swipe to remove demo</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n        --bg: #ffffff;\n        --fg: #1a1a1a;\n        --accent: #0b57d0;\n      }\n      @media (prefers-color-scheme: dark) {\n        :root {\n          --bg: #121212;\n          --fg: #f0f0f0;\n          --accent: #8ab4f8;\n        }\n      }\n      body {\n        margin: 0;\n        padding: 2rem 1rem;\n        font:\n          1rem/1.5 system-ui,\n          sans-serif;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      main {\n        max-width: 32rem;\n        margin: 0 auto;\n      }\n      .field {\n        margin-bottom: 1rem;\n      }\n      label {\n        display: block;\n        font-weight: 600;\n      }\n      .check {\n        font-weight: 400;\n      }\n      input:not([type=\"checkbox\"]) {\n        box-sizing: border-box;\n        width: 100%;\n        padding: 0.5rem;\n        font: inherit;\n      }\n      fieldset {\n        margin: 0 0 1rem;\n        border: 1px solid currentColor;\n      }\n      button {\n        padding: 0.5rem 1rem;\n        font: inherit;\n      }\n      :focus-visible {\n        outline: 3px solid var(--accent);\n        outline-offset: 2px;\n      }\n      ul {\n        padding: 0;\n        list-style: none;\n      }\n      .line {\n        display: flex;\n        gap: 1rem;\n        align-items: center;\n        justify-content: space-between;\n        padding: 0.75rem;\n        margin-bottom: 0.5rem;\n        border: 1px solid currentColor;\n        background: var(--bg);\n        touch-action: pan-y;\n        user-select: none;\n      }\n      .visually-hidden {\n        position: absolute;\n        width: 1px;\n        height: 1px;\n        overflow: hidden;\n        clip-path: inset(50%);\n        white-space: nowrap;\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <h1>Cart</h1>\n      <ul id=\"lines\">\n        <li class=\"line\">\n          <span>Rain jacket</span\n          ><button type=\"button\" class=\"remove\">Remove Rain jacket</button>\n        </li>\n        <li class=\"line\">\n          <span>Hiking boot</span\n          ><button type=\"button\" class=\"remove\">Remove Hiking boot</button>\n        </li>\n      </ul>\n      <p role=\"status\" id=\"cart-status\" class=\"visually-hidden\"></p>\n    </main>\n    <script>\n      const status = document.getElementById(\"cart-status\");\n\n      function removeLine(row) {\n        const name = row.querySelector(\"span\").textContent;\n        row.remove();\n        status.textContent = `${name} removed from cart`;\n        setTimeout(() => {\n          status.textContent = \"\";\n        }, 3000);\n      }\n\n      function swipeable(row) {\n        let startX = null;\n        let dx = 0;\n\n        row.addEventListener(\"pointerdown\", (event) => {\n          if (event.target.closest(\"button\")) return;\n          startX = event.clientX;\n          row.setPointerCapture(event.pointerId);\n        });\n\n        row.addEventListener(\"pointermove\", (event) => {\n          if (startX === null) return;\n          dx = Math.min(0, event.clientX - startX);\n          row.style.transform = `translateX(${dx}px)`;\n        });\n\n        const end = (event) => {\n          if (startX === null) return;\n          const past = event.type === \"pointerup\" && -dx > row.offsetWidth / 2;\n          startX = null;\n          dx = 0;\n          row.style.transform = \"\";\n          if (past) removeLine(row);\n        };\n\n        row.addEventListener(\"pointerup\", end);\n        row.addEventListener(\"pointercancel\", end);\n      }\n\n      for (const row of document.querySelectorAll(\".line\")) {\n        row\n          .querySelector(\".remove\")\n          .addEventListener(\"click\", () => removeLine(row));\n        swipeable(row);\n      }\n    </script>\n  </body>\n</html>\n",
