    "demo": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Time limit warning demo</title>\n    <style>\n      :root {\n        color-scheme: light dark;\n        --bg: #ffffff;\n        --fg: #1a1a1a;\n        --accent: #0b57d0;\n      }\n      @media (prefers-color-scheme: dark) {\n        :root {\n          --bg: #121212;\n          --fg: #f0f0f0;\n          --accent: #8ab4f8;\n        }\n      }\n      body {\n        margin: 0;\n        padding: 2rem 1rem;\n        font:\n          1rem/1.5 system-ui,\n          sans-serif;\n        background: var(--bg);\n        color: var(--fg);\n      }\n      main {\n        max-width: 32rem;\n        margin: 0 auto;\n      }\n      .field {\n        margin-bottom: 1rem;\n      }\n      label {\n        display: block;\n        font-weight: 600;\n      }\n      .check {\n        font-weight: 400;\n      }\n      input:not([type=\"checkbox\"]) {\n        box-sizing: border-box;\n        width: 100%;\n        padding: 0.5rem;\n        font: inherit;\n      }\n      fieldset {\n        margin: 0 0 1rem;\n        border: 1px solid currentColor;\n      }\n      button {\n        padding: 0.5rem 1rem;\n        font: inherit;\n      }\n      :focus-visible {\n        outline: 3px solid var(--accent);\n        outline-offset: 2px;\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <h1>Outdoor gear</h1>\n      <div role=\"alert\" id=\"hold-warning\" hidden>\n        <p>\n          Your cart is held for 2 more minutes. Then the items go back in stock.\n        </p>\n        <button type=\"button\" id=\"extend\">\n          Keep my items for 15 more minutes\n        </button>\n      </div>\n      <div role=\"status\" id=\"hold-expired\"></div>\n      <p>Rain jacket, €189.00</p>\n      <button type=\"button\" id=\"add\">Add to cart</button>\n      <p id=\"count\">Cart: 0 items</p>\n    </main>\n    <script>\n      const HOLD_MS = 15 * 60 * 1000;\n      const WARN_MS = 2 * 60 * 1000;\n      const warning = document.getElementById(\"hold-warning\");\n      const expired = document.getElementById(\"hold-expired\");\n      const count = document.getElementById(\"count\");\n      let items = 0;\n      let warnTimer;\n      let endTimer;\n\n      function startHold() {\n        clearTimeout(warnTimer);\n        clearTimeout(endTimer);\n        warning.hidden = true;\n        warnTimer = setTimeout(() => {\n          warning.hidden = false;\n        }, HOLD_MS - WARN_MS);\n        endTimer = setTimeout(() => {\n          items = 0;\n          count.textContent = \"Cart: 0 items\";\n          warning.hidden = true;\n          expired.textContent =\n            \"Your cart expired, the items are back in stock.\";\n        }, HOLD_MS);\n      }\n\n      document.getElementById(\"add\").addEventListener(\"click\", () => {\n        if (items === 0) startHold();\n        items += 1;\n        expired.textContent = \"\";\n        count.textContent = `Cart: ${items} items`;\n      });\n\n      document.getElementById(\"extend\").addEventListener(\"click\", startHold);\n    </script>\n  </body>\n</html>\n",
